summary={'n_students':int(feas.students.sum()),'n_schools':int(feas.schools.sum()),'models':len(main),'forest_contrasts':len(fc),'holm_significant':int((fc.p_holm<.05).sum()),'between_min':float(desc[desc.term=='between_share'].est.min()),'between_max':float(desc[desc.term=='between_share'].est.max())}
